import{_ as i,a0 as t,w as d,s as c,ao as o,I as l,x as a,a1 as p,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const V=JSON.parse('{"title":"使用 LVM 添加存储 | LCTT x X-CMD","titleTemplate":false,"description":"使用 LVM 添加存储 | LCTT (202112) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 LVM 添加存储 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 LVM 添加存储 | LCTT (202112) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202112/20210922 Add storage with LVM","title":"使用 LVM 添加存储","tag":"202112","desc":""},"relativePath":"202112/20210922 Add storage with LVM.md","filePath":"[post].md"}'),r={name:"202112/20210922 Add storage with LVM.md"};function h(v,s,u,g,m,k){const n=t("Link");return d(),c("div",null,[s[18]||(s[18]=o(`<h1 id="使用-lvm-添加存储" tabindex="-1">使用 LVM 添加存储 <a class="header-anchor" href="#使用-lvm-添加存储" aria-label="Permalink to “使用 LVM 添加存储”">​</a></h1><blockquote><p>LVM 为你配置存储的方式提供了极大的灵活性。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202112/13/235125wn99nloup38jnkoo.jpg" alt=""></p><p><ruby>逻辑卷管理器<rt>Logical Volume Manager</rt></ruby>（LVM）允许在操作系统和硬件之间建立一个抽象层。通常，你的操作系统会查找磁盘（<code>/dev/sda</code>、<code>/dev/sdb</code> 等）和这些磁盘中的分区（<code>/dev/sda1</code>、<code>/dev/sdb1</code> 等）。</p><p>LVM 在操作系统和磁盘之间创建了一个虚拟层。LVM 不是一个驱动器持有一定数量的分区，而是创建一个统一的存储池（称为<ruby>卷组<rt>Volume Group</rt></ruby>），跨越任意数量的物理驱动器（称为<ruby>物理卷<rt>Physical Volume</rt></ruby>）。使用卷组中可用的存储，LVM 可以为你的操作系统提供类似磁盘和分区的功能。</p><p>操作系统完全没有意识到它被“欺骗”了。</p><p><img src="https://opensource.com/sites/default/files/lvm.png" alt="Drive space" title="Drive space"></p><p>由于 LVM 虚拟地创建卷组和逻辑卷，因此即使在系统运行时，也可以轻松调整它们的大小或移动它们，或者创建新卷。此外，LVM 提供了其它情况下不存在的特性，比如创建逻辑卷的活动快照时无需首先卸载磁盘。</p><p>LVM 中的卷组是一个命名的虚拟容器，将底层物理磁盘组合在一起。它充当一个池，可以从中创建不同大小的<ruby>逻辑卷<rt>Logical Volume</rt></ruby>。逻辑卷包含实际的文件系统并且可以跨越多个磁盘，并且不需要物理上连续。</p><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to “特性”">​</a></h3><ul><li>分区名称通常具有系统名称，例如 <code>/dev/sda1</code>。LVM 具有便于人们理解的名称，例如 <code>home</code> 或者 <code>media</code>。</li><li>分区的总大小受底层物理磁盘大小的限制。在 LVM 中，卷可以跨越多个磁盘，并且仅受 LVM 中所有物理磁盘总大小的限制。</li><li>分区通常只有在磁盘未使用且已卸载时才能调整大小、移动或删除。LVM 卷可以在系统运行时进行操作。</li><li>只能通过分配与分区相邻的可用空间来扩展分区。LVM 卷可以从任何地方占用可用空间。</li><li>扩展分区涉及移动数据以腾出可用空间，这非常耗时，并且可能会在断电期间导致数据丢失。LVM 卷可以从卷组中的任何地方占用可用空间，甚至可以在另一块磁盘上。</li><li>因为在 LVM 中创建卷非常容易，所以它鼓励创建不同的卷，例如创建单独的卷来测试功能或尝试不同的操作系统。对于分区，此过程将非常耗时并且容易出错。</li><li>快照只能在 LVM 中创建。它允许你创建当前逻辑卷的时间点镜像，即使在系统运行时也可以。这非常适合备份。</li></ul><h3 id="测试设置" tabindex="-1">测试设置 <a class="header-anchor" href="#测试设置" aria-label="Permalink to “测试设置”">​</a></h3><p>作为演示，假设你的系统具有以下驱动器配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>NAME    MAJ:MIN RM SIZE RO TYPE MOUNTPOINT</span></span>
<span class="line"><span>xvda    202:0    0   8G  0 disk</span></span>
<span class="line"><span>\`-xvda1 202:1    0   8G  0 part /</span></span>
<span class="line"><span>xvdb    202:16   0   1G  0 disk</span></span>
<span class="line"><span>xvdc    202:32   0   1G  0 disk</span></span>
<span class="line"><span>xvdd    202:48   0   2G  0 disk</span></span>
<span class="line"><span>xvde    202:64   0   5G  0 disk</span></span>
<span class="line"><span>xvdf    202:80   0   8G  0 disk</span></span></code></pre></div><h4 id="步骤-1-初始化磁盘以用于-lvm" tabindex="-1">步骤 1. 初始化磁盘以用于 LVM <a class="header-anchor" href="#步骤-1-初始化磁盘以用于-lvm" aria-label="Permalink to “步骤 1. 初始化磁盘以用于 LVM”">​</a></h4><p>运行 <code>pvcreate /dev/xvdb /dev/xvdc /dev/xvdd /dev/xvde /dev/xvdf</code>。输出应如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Physical volume &quot;/dev/xvdb&quot; successfully created</span></span>
<span class="line"><span>Physical volume &quot;/dev/xvdc&quot; successfully created</span></span>
<span class="line"><span>Physical volume &quot;/dev/xvdd&quot; successfully created</span></span>
<span class="line"><span>Physical volume &quot;/dev/xvde&quot; successfully created</span></span>
<span class="line"><span>Physical volume &quot;/dev/xvdf&quot; successfully created</span></span></code></pre></div><p>使用 <code>pvs</code> 或者 <code>pvdisplay</code> 查看结果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;/dev/xvde&quot; is a new physical volume of &quot;5.00 GiB&quot;</span></span>
<span class="line"><span>--- NEW Physical volume ---</span></span>
<span class="line"><span>PV Name               /dev/xvde</span></span>
<span class="line"><span>VG Name</span></span>
<span class="line"><span>PV Size               5.00 GiB</span></span>
<span class="line"><span>Allocatable           NO</span></span>
<span class="line"><span>PE Size               0</span></span>
<span class="line"><span>Total PE              0</span></span>
<span class="line"><span>Free PE               0</span></span>
<span class="line"><span>Allocated PE          0</span></span>
<span class="line"><span>PV UUID               728JtI-ffZD-h2dZ-JKnV-8IOf-YKdS-8srJtn</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;/dev/xvdb&quot; is a new physical volume of &quot;1.00 GiB&quot;</span></span>
<span class="line"><span>--- NEW Physical volume ---</span></span>
<span class="line"><span>PV Name               /dev/xvdb</span></span>
<span class="line"><span>VG Name</span></span>
<span class="line"><span>PV Size               1.00 GiB</span></span>
<span class="line"><span>Allocatable           NO</span></span>
<span class="line"><span>PE Size               0</span></span>
<span class="line"><span>Total PE              0</span></span>
<span class="line"><span>Free PE               0</span></span>
<span class="line"><span>Allocated PE          0</span></span>
<span class="line"><span>PV UUID               zk1phS-7uXc-PjBP-5Pv9-dtAV-zKe6-8OCRkZ</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;/dev/xvdd&quot; is a new physical volume of &quot;2.00 GiB&quot;</span></span>
<span class="line"><span>--- NEW Physical volume ---</span></span>
<span class="line"><span>PV Name               /dev/xvdd</span></span>
<span class="line"><span>VG Name</span></span>
<span class="line"><span>PV Size               2.00 GiB</span></span>
<span class="line"><span>Allocatable           NO</span></span>
<span class="line"><span>PE Size               0</span></span>
<span class="line"><span>Total PE              0</span></span>
<span class="line"><span>Free PE               0</span></span>
<span class="line"><span>Allocated PE          0</span></span>
<span class="line"><span>PV UUID               R0I139-Ipca-KFra-2IZX-o9xJ-IW49-T22fPc</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;/dev/xvdc&quot; is a new physical volume of &quot;1.00 GiB&quot;</span></span>
<span class="line"><span>--- NEW Physical volume ---</span></span>
<span class="line"><span>PV Name               /dev/xvdc</span></span>
<span class="line"><span>VG Name</span></span>
<span class="line"><span>PV Size               1.00 GiB</span></span>
<span class="line"><span>Allocatable           NO</span></span>
<span class="line"><span>PE Size               0</span></span>
<span class="line"><span>Total PE              0</span></span>
<span class="line"><span>Free PE               0</span></span>
<span class="line"><span>Allocated PE          0</span></span>
<span class="line"><span>PV UUID               FDzcVS-sq22-2b13-cYRj-dXHf-QLjS-22Meae</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;/dev/xvdf&quot; is a new physical volume of &quot;8.00 GiB&quot;</span></span>
<span class="line"><span>--- NEW Physical volume ---</span></span>
<span class="line"><span>PV Name               /dev/xvdf</span></span>
<span class="line"><span>VG Name</span></span>
<span class="line"><span>PV Size               8.00 GiB</span></span>
<span class="line"><span>Allocatable           NO</span></span>
<span class="line"><span>PE Size               0</span></span>
<span class="line"><span>Total PE              0</span></span>
<span class="line"><span>Free PE               0</span></span>
<span class="line"><span>Allocated PE          0</span></span>
<span class="line"><span>PV UUID               TRVSH9-Bo5D-JHHb-g0NX-8IoS-GG6T-YV4d0p</span></span></code></pre></div><h4 id="步骤-2-创建卷组" tabindex="-1">步骤 2. 创建卷组 <a class="header-anchor" href="#步骤-2-创建卷组" aria-label="Permalink to “步骤 2. 创建卷组”">​</a></h4><p>运行 <code>vgcreate myvg /dev/xvdb /dev/xvdc /dev/xvdd /dev/xvde /dev/xvdf</code>。通过 <code>vgs</code> 或者 <code>vgdisplay</code> 查看结果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>--- Volume group ---</span></span>
<span class="line"><span>VG Name               myvg</span></span>
<span class="line"><span>System ID</span></span>
<span class="line"><span>Format                lvm2</span></span>
<span class="line"><span>Metadata Areas        5</span></span>
<span class="line"><span>Metadata Sequence No  1</span></span>
<span class="line"><span>VG Access             read/write</span></span>
<span class="line"><span>VG Status             resizable</span></span>
<span class="line"><span>MAX LV                0</span></span>
<span class="line"><span>Cur LV                0</span></span>
<span class="line"><span>Open LV               0</span></span>
<span class="line"><span>Max PV                0</span></span>
<span class="line"><span>Cur PV                5</span></span>
<span class="line"><span>Act PV                5</span></span>
<span class="line"><span>VG Size               16.98 GiB</span></span>
<span class="line"><span>PE Size               4.00 MiB</span></span>
<span class="line"><span>Total PE              4347</span></span>
<span class="line"><span>Alloc PE / Size       0 / 0</span></span>
<span class="line"><span>Free  PE / Size       4347 / 16.98 GiB</span></span>
<span class="line"><span>VG UUID               ewrrWp-Tonj-LeFa-4Ogi-BIJJ-vztN-yrepkh</span></span></code></pre></div><h4 id="步骤-3-创建逻辑卷" tabindex="-1">步骤 3: 创建逻辑卷 <a class="header-anchor" href="#步骤-3-创建逻辑卷" aria-label="Permalink to “步骤 3: 创建逻辑卷”">​</a></h4><p>运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lvcreate myvg --name media --size 4G</span></span>
<span class="line"><span>lvcreate myvg --name home --size 4G</span></span></code></pre></div><p>使用 <code>lvs</code> 或者 <code>lvdisplay</code> 验证结果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>--- Logical volume ---</span></span>
<span class="line"><span>LV Path                /dev/myvg/media</span></span>
<span class="line"><span>LV Name                media</span></span>
<span class="line"><span>VG Name                myvg</span></span>
<span class="line"><span>LV UUID                LOBga3-pUNX-ZnxM-GliZ-mABH-xsdF-3VBXFT</span></span>
<span class="line"><span>LV Write Access        read/write</span></span>
<span class="line"><span>LV Creation host, time ip-10-0-5-236, 2017-02-03 05:29:15 +0000</span></span>
<span class="line"><span>LV Status              available</span></span>
<span class="line"><span># open                 0</span></span>
<span class="line"><span>LV Size                4.00 GiB</span></span>
<span class="line"><span>Current LE             1024</span></span>
<span class="line"><span>Segments               1</span></span>
<span class="line"><span>Allocation             inherit</span></span>
<span class="line"><span>Read ahead sectors     auto</span></span>
<span class="line"><span>- currently set to     256</span></span>
<span class="line"><span>Block device           252:0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--- Logical volume ---</span></span>
<span class="line"><span>LV Path                /dev/myvg/home</span></span>
<span class="line"><span>LV Name                home</span></span>
<span class="line"><span>VG Name                myvg</span></span>
<span class="line"><span>LV UUID                Hc06sl-vtss-DuS0-jfqj-oNce-qKf6-e5qHhK</span></span>
<span class="line"><span>LV Write Access        read/write</span></span>
<span class="line"><span>LV Creation host, time ip-10-0-5-236, 2017-02-03 05:29:40 +0000</span></span>
<span class="line"><span>LV Status              available</span></span>
<span class="line"><span># open                 0</span></span>
<span class="line"><span>LV Size                4.00 GiB</span></span>
<span class="line"><span>Current LE             1024</span></span>
<span class="line"><span>Segments               1</span></span>
<span class="line"><span>Allocation             inherit</span></span>
<span class="line"><span>Read ahead sectors     auto</span></span>
<span class="line"><span>- currently set to     256</span></span>
<span class="line"><span>Block device           252:1</span></span></code></pre></div><h4 id="步骤-4-创建文件系统" tabindex="-1">步骤 4: 创建文件系统 <a class="header-anchor" href="#步骤-4-创建文件系统" aria-label="Permalink to “步骤 4: 创建文件系统”">​</a></h4><p>使用以下命令创建文件系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vgcreate myvg /dev/xvdb /dev/xvdc /dev/xvdd /dev/xvde /dev/xvdf</span></span>
<span class="line"><span>mkfs.ext3 /dev/myvg/media</span></span>
<span class="line"><span>mkfs.ext3 /dev/myvg/home</span></span></code></pre></div><p>挂载它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mount /dev/myvg/media /media</span></span>
<span class="line"><span>mount /dev/myvg/home /home</span></span></code></pre></div><p>使用 <code>lsblk</code> 命令查看完整配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>NAME         MAJ:MIN RM SIZE RO TYPE MOUNTPOINT</span></span>
<span class="line"><span>xvda         202:0    0   8G  0 disk</span></span>
<span class="line"><span>\`-xvda1      202:1    0   8G  0 part /</span></span>
<span class="line"><span>xvdb         202:16   0   1G  0 disk</span></span>
<span class="line"><span>xvdc         202:32   0   1G  0 disk</span></span>
<span class="line"><span>xvdd         202:48   0   2G  0 disk</span></span>
<span class="line"><span>xvde         202:64   0   5G  0 disk</span></span>
<span class="line"><span>\`-myvg-media 252:0    0   4G  0 lvm  /media</span></span>
<span class="line"><span>xvdf         202:80   0   8G  0 disk</span></span>
<span class="line"><span>\`-myvg-home  252:1    0   4G  0 lvm  /home</span></span></code></pre></div><h4 id="步骤-5-扩展-lvm" tabindex="-1">步骤 5: 扩展 LVM <a class="header-anchor" href="#步骤-5-扩展-lvm" aria-label="Permalink to “步骤 5: 扩展 LVM”">​</a></h4><p>添加一块新的 <code>/dev/xvdg</code> 磁盘。要扩展 <code>home</code> 卷，运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pvcreate /dev/xvdg</span></span>
<span class="line"><span>vgextend myvg /dev/xvdg</span></span>
<span class="line"><span>lvextend -l 100%FREE /dev/myvg/home</span></span>
<span class="line"><span>resize2fs /dev/myvg/home</span></span></code></pre></div><p>运行 <code>df -h</code>，你应该可以看到新的磁盘大小。</p><p>就是这样！</p><p>LVM 为你配置存储的方式提供了极大的灵活性。尝试一下，并享受 LVM 的乐趣！</p>`,40)),l("p",null,[s[1]||(s[1]=a("本文首发于 ",-1)),p(n,{href:"https://notes.ayushsharma.in/2017/02/working-with-logical-volume-manager-lvm"},{default:e(()=>[...s[0]||(s[0]=[a("作者个人博客",-1)])]),_:1}),s[2]||(s[2]=a("，经授权改编。",-1))]),s[19]||(s[19]=l("hr",null,null,-1)),l("p",null,[s[4]||(s[4]=a("via: ",-1)),p(n,{href:"https://opensource.com/article/21/9/add-storage-lvm"},{default:e(()=>[...s[3]||(s[3]=[a("https://opensource.com/article/21/9/add-storage-lvm",-1)])]),_:1})]),l("p",null,[s[9]||(s[9]=a("作者：",-1)),p(n,{href:"https://opensource.com/users/ayushsharma"},{default:e(()=>[...s[5]||(s[5]=[a("Ayush Sharma",-1)])]),_:1}),s[10]||(s[10]=a(" 选题：",-1)),p(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 译者：",-1)),p(n,{href:"https://github.com/perfiffer"},{default:e(()=>[...s[7]||(s[7]=[a("perfiffer",-1)])]),_:1}),s[12]||(s[12]=a(" 校对：",-1)),p(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[15]||(s[15]=a("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原创编译，",-1)),p(n,{href:"https://linux.cn/"},{default:e(()=>[...s[14]||(s[14]=[a("Linux中国",-1)])]),_:1}),s[17]||(s[17]=a(" 荣誉推出",-1))])])}const y=i(r,[["render",h]]);export{V as __pageData,y as default};
